package org.sormus.downloads;
import android.content.*;import android.net.Uri;import java.util.*;
/** Validated handoff shared by the transparent receiver and manual UI. */
final class IncomingTransfer {
 final ArrayList<Uri> files=new ArrayList<>();String link="";
 static IncomingTransfer read(Intent intent)throws Exception{if(intent==null||!TransferInbox.external(intent.getAction()))return null;IncomingTransfer out=new IncomingTransfer();if(Intent.ACTION_SEND_MULTIPLE.equals(intent.getAction())){ArrayList<Uri> list=intent.getParcelableArrayListExtra(Intent.EXTRA_STREAM);if(list!=null)for(Uri uri:list)out.add(uri);}else out.add(intent.getParcelableExtra(Intent.EXTRA_STREAM));if(Intent.ACTION_VIEW.equals(intent.getAction())&&intent.getData()!=null){if("content".equalsIgnoreCase(intent.getData().getScheme()))out.add(intent.getData());else out.link=intent.getData().toString().trim();}if(out.files.isEmpty()&&out.link.isEmpty()&&intent.getClipData()!=null)for(int n=0;n<intent.getClipData().getItemCount();n++)out.add(intent.getClipData().getItemAt(n).getUri());if(out.files.isEmpty()&&out.link.isEmpty()){String text=intent.getStringExtra(Intent.EXTRA_TEXT);if(text!=null)out.link=text.trim();}if(!out.files.isEmpty())out.link="";if(out.files.isEmpty()&&!TransferProtocol.link(out.link))throw new Exception("Share a file, magnet or direct torrent link.");return out;}
 private void add(Uri uri)throws Exception{if(uri==null)return;if(!"content".equalsIgnoreCase(uri.getScheme()))throw new Exception("Share files through Android's file picker.");uri=uri.normalizeScheme();if(!files.contains(uri)){if(files.size()>=20)throw new Exception("Share up to 20 files at a time.");files.add(uri);}}
 static Intent serviceIntent(Context context,ArrayList<Uri> files,String link){Intent job=new Intent(context,TransferService.class);job.putExtra("batchId",UUID.randomUUID().toString());job.putParcelableArrayListExtra("files",new ArrayList<>(files));job.putExtra("link",link);ClipData clip=ClipData.newPlainText("transfer","");for(Uri uri:files)clip.addItem(new ClipData.Item(uri));job.setClipData(clip);job.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);return job;}
 void start(Context context){context.startForegroundService(serviceIntent(context,files,link));}
 static boolean paired(Context context){DownloadsApi api=new DownloadsApi(context);try{TransferProtocol.server(api.preferences.getString("server",""));return api.preferences.getString("token","").matches("[a-f0-9]{64}");}catch(Exception e){return false;}}
}
